#include "practice.h"
#include <cassert>
#include <iostream>
using namespace workbench;
std::vector<Part> load_parts(char const* path){
    std::ifstream f(path);Json j;f>>j;std::vector<Part> out;
    for(auto const& x:j.at("parts")){Part p;p.id=x.at("id");p.volume.shape=x.at("shape");p.volume.local=pose(x.at("local"));p.volume.radius=x.at("radius_metres");p.volume.half=vector(x.at("half_extents_metres"));p.volume.half_length=x.at("half_length_metres");p.volume.snap_distance=x.at("snap_distance_metres");p.volume.snap_angle=x.at("snap_angle_radians");p.volume.release_distance=x.at("release_distance_metres");out.push_back(p);}seed_game_poses(out);return out;
}
struct Fixture {
    std::vector<Part> parts;Practice p;PracticeSettings settings;PracticeFrame f;std::uint64_t serial{};
    Fixture(std::vector<Part> a,bool empty=false):parts(std::move(a)){settings.snap_seconds=0;f.head={{0,1.7,0},{}};f.eye=f.head;f.time_ns=1'000'000'000;f.controllers[0].valid=f.controllers[1].valid=true;p.reset({{0,1,-.5},{}},f.head,empty);p.resume(settings,1);at(0);tick();}
    void tick(int count=1,bool rendered=true){for(int i=0;i<count;++i){f.time_ns+=10'000'000;p.step(f,parts);if(rendered)p.acknowledge_render(++serial);}}
    void at(unsigned part){unsigned side=part?0:1;auto target=compose(p.gun(),effective_wrist(parts[part],side,p.frame()));f.controllers[side].grip=compose(target,inverse(controller_wrist_mount(side,part==0)));}
    void take(){at(0);f.controllers[1].squeeze=0;tick();f.controllers[1].squeeze=1;tick();assert(p.main_held());tick(5);}
    void left_release(){f.controllers[0].squeeze=f.controllers[0].trigger=0;tick();}
    void left_to(P goal,int steps=100){auto start=f.controllers[0].grip;for(int i=1;i<=steps;++i){f.controllers[0].grip=mix(start,goal,double(i)/steps);tick();}}
    P seated_mag_grip(double depth){auto w=compose(p.gun(),effective_wrist(parts[2],0,Frame{}));w.position=add(w.position,rotate(p.gun().orientation,{0,-depth,0}));return compose(w,inverse(controller_wrist_mount(0,false)));}
    void extract(){take_part(2);auto start=f.controllers[0].grip.position;for(unsigned i=1;i<=15;++i){f.controllers[0].grip.position=add(start,rotate(p.gun().orientation,{0,-.004*i,0}));tick();}assert(!p.mag_seated());}
    void take_part(unsigned part){left_release();at(part);tick();f.controllers[0].squeeze=1;tick();if(p.off_part()!=int(part)){std::cerr<<"take part "<<part<<" got "<<p.off_part()<<" "<<p.status()<<"\n";assert(false);}}
};
int main(int argc,char** argv){assert(argc==2);auto parts=load_parts(argv[1]);assert(parts.size()==5);
    for(auto const& part:parts)for(unsigned side=0;side<2;++side)if(part.known[side]){auto const& g=part.poses[side];assert(g.authored_default&&!g.fully_tracked&&g.source_time==0&&g.data_source==0);auto q=from_raw_wrist(to_raw_wrist(g.wrist_in_object));assert(length(sub(q.position,g.wrist_in_object.position))<1e-8&&rotation_error(q.orientation,g.wrist_in_object.orientation)<1e-6);for(auto const& j:g.raw_in_object)assert(j.flags==0);}
    {PracticeSettings s;s.shoulder_adjust={.1,-.04,.02};s.shoulder_scale=1.2;auto q=PracticeSettings::parse(s.json());assert(q.shoulder_scale==s.shoulder_scale&&q.shoulder_adjust.x==.1);auto bad=s.json();bad["preview_fire_interval"]=0;try{PracticeSettings::parse(bad);assert(false);}catch(std::runtime_error const&){} }
    {Fixture a(parts);a.f.controllers[1].squeeze=1;a.p.resume(a.settings,1);a.tick();assert(!a.p.main_held());a.take();a.f.controllers[1].trigger=1;a.tick();assert(a.p.shots()==1&&a.p.loaded()==29);a.tick(11);assert(a.p.shots()==2);a.f.suppress_actions=true;a.tick(20);auto n=a.p.shots();a.f.suppress_actions=false;a.tick(20);assert(a.p.shots()==n);a.f.controllers[1].trigger=0;a.tick();a.f.controllers[1].trigger=1;a.tick();assert(a.p.shots()==n+1);a.f.controllers[1].valid=false;a.tick();assert(!a.p.main_held());a.f.controllers[1].valid=true;a.tick();assert(!a.p.main_held());}
    {Fixture a(parts);auto shoulder=a.p.shoulder();assert(a.p.shoulder_contains(shoulder.position));a.f.head.orientation=axis({0,1,0},1.3);a.tick();assert(length(sub(a.p.shoulder().position,shoulder.position))<1e-10);a.f.head.position.x+=.2;a.tick();assert(std::abs(a.p.shoulder().position.x-shoulder.position.x-.2)<1e-10);a.take();a.f.controllers[0].grip=a.p.shoulder();a.left_release();a.f.controllers[0].squeeze=1;a.tick();assert(a.p.off_part()!=2);}
    for(bool empty:{false,true}){Fixture a(parts,empty);a.take();a.extract();a.left_release();a.f.controllers[0].grip=a.p.shoulder();a.tick();a.f.controllers[0].squeeze=1;a.tick();assert(a.p.off_part()==2);assert(a.p.reserve()==(empty?300u:330u));a.left_to(a.seated_mag_grip(.15));assert(!a.p.mag_seated());a.left_to(a.seated_mag_grip(.03),40);a.tick(30);assert(a.p.mag_seated()&&a.p.loaded()==60);assert(a.p.chambered()==!empty);
        if(empty){a.take_part(3);auto start=a.f.controllers[0].grip.position;for(unsigned i=1;i<=15;++i){a.f.controllers[0].grip.position=add(start,rotate(a.p.gun().orientation,{0,0,.01*i}));a.tick();}a.left_release();a.tick(30);assert(a.p.chambered()&&a.p.cycles()==1);}a.f.controllers[1].trigger=1;a.tick();assert(a.p.shots()==1&&a.p.loaded()==59);}
    {Fixture a(parts);a.take();a.extract();a.left_to(a.seated_mag_grip(.12),25);a.left_to(a.seated_mag_grip(.03),40);a.tick(30);assert(a.p.mag_seated()&&a.p.loaded()==30&&a.p.reserve()==360);}
    {Fixture a(parts,true);a.take();a.take_part(3);auto start=a.f.controllers[0].grip.position;for(unsigned i=1;i<=12;++i){a.f.controllers[0].grip.position=add(start,{0,0,.01*i});a.tick();}a.left_release();a.tick(25);assert(!a.p.chambered());a.take_part(3);start=a.f.controllers[0].grip.position;for(unsigned i=1;i<=15;++i){a.f.controllers[0].grip.position=add(start,{0,0,.01*i});a.tick();}a.left_release();a.tick(30);assert(!a.p.chambered()&&a.p.cycles()==1);}
    {Fixture a(parts);a.take();a.at(4);a.tick(30);assert(!a.p.motor());a.take_part(4);auto start=a.f.controllers[0].grip.position;for(unsigned i=1;i<=20;++i){a.f.controllers[0].grip.position=add(start,{0,0,-.004*i});a.tick();}a.tick(25);assert(a.p.motor());a.tick(400);assert(a.p.motor());a.left_release();assert(a.p.motor());a.tick(301);assert(!a.p.motor());a.f.controllers[0].grip.position={-1,1,-1};a.tick(60);assert(a.p.starter_progress()<1e-8&&a.p.frame().starter_angle<1e-8);a.at(4);a.tick(30);assert(a.p.frame().starter_angle>1.56&&a.p.starter_progress()<1e-8&&!a.p.motor());a.f.controllers[0].grip.position={-1,1,-1};a.tick(30);assert(a.p.frame().starter_angle<1e-8);}
    {Fixture a(parts);a.take();a.settings.two_hand=false;a.p.settings(a.settings);a.take_part(1);a.f.controllers[0].grip.position.x+=.3;a.tick();assert(a.p.off_part()==-1);a.f.controllers[0].squeeze=0;a.tick();a.at(1);a.parts[1].volume.radius=.001;a.parts[1].volume.local.position={5,5,5};a.f.controllers[0].squeeze=1;a.tick();assert(a.p.off_part()==-1);}
    {Fixture a(parts,true);a.take();a.take_part(3);auto start=a.f.controllers[0].grip.position;for(unsigned i=1;i<=15;++i){a.f.controllers[0].grip.position=add(start,{0,0,.01*i});a.tick(1,false);}a.f.controllers[0].squeeze=0;a.tick(1,false);a.tick(30,false);assert(a.p.cycles()==0);a.tick(30);assert(a.p.cycles()==1&&!a.p.chambered());}
    {Fixture a(parts);a.take();a.at(4);a.tick(30);a.take_part(4);auto start=a.f.controllers[0].grip.position;for(unsigned i=1;i<=20;++i){a.f.controllers[0].grip.position=add(start,{0,0,-.004*i});a.tick(1,false);}a.tick(30,false);assert(!a.p.motor());a.tick(5);assert(a.p.motor());for(unsigned i=1;i<=20;++i){a.f.controllers[0].grip.position=add(start,{0,0,-.08+.004*i});a.tick();}assert(!a.p.motor());for(unsigned i=1;i<=20;++i){a.f.controllers[0].grip.position=add(start,{0,0,-.004*i});a.tick();}a.tick(20);assert(a.p.motor());a.f.controllers[0].valid=false;a.tick();assert(!a.p.motor());}
    {Fixture a(parts);a.take();a.f.time_ns+=150'000'000;a.tick();assert(!a.p.main_held());a.tick();assert(!a.p.main_held());a.take();a.f.epoch=2;a.tick();assert(!a.p.main_held());}
    {Fixture a(parts);a.take();a.f.controllers[1].aim_valid=true;for(double pitch:{0.,.4,-.5}){a.f.controllers[1].aim.orientation=axis({1,0,0},pitch);a.f.controllers[1].grip.orientation=axis({1,0,0},1.3);a.tick();assert(rotation_error(a.p.gun().orientation,a.f.controllers[1].aim.orientation)<1e-6);}a.parts[0].wrist_degrees[1]={25,0,0};a.p.resume(a.settings,1);a.f.controllers[1].aim_valid=false;a.take();a.f.controllers[1].aim_valid=true;a.f.controllers[1].aim.orientation={};a.tick();assert(rotation_error(a.p.gun().orientation,Q{})<1e-6);}
    {Fixture a(parts);a.take();a.extract();assert(a.p.mag_visible());a.left_release();assert(!a.p.mag_visible());for(int cycle=0;cycle<3;++cycle){a.f.controllers[0].grip=a.p.shoulder();a.tick();a.f.controllers[0].squeeze=1;a.tick();assert(a.p.off_part()==2&&a.p.mag_visible());a.left_to(a.seated_mag_grip(.15));a.left_to(a.seated_mag_grip(.03),40);a.tick(30);assert(a.p.mag_seated()&&a.p.loaded()==60);a.extract();a.left_release();assert(!a.p.mag_visible());}}
    std::cout<<"PASS: portable Quest practice adapter; authored bases, fresh input, firing, stable shoulder, extraction/replacement, observed E stroke and C hold/tail. CPU trajectories only.\n";
}
